-- AlterEnum
BEGIN;
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM "FormalProject" WHERE "status"::text = 'ESCALATED') THEN
    RAISE EXCEPTION 'ProjectStatus ESCALATED is still in use; resolve those projects before running migration 5';
  END IF;
END $$;
CREATE TYPE "ProjectStatus_new" AS ENUM ('PROTOCOL_DRAFT', 'PROTOCOL_SUBMITTED', 'UNDER_REVIEW', 'REVISION_REQUIRED', 'MANUSCRIPT_SUBMITTED', 'APPROVED', 'REJECTED', 'APPEAL');
