ALTER TYPE "ProjectStatus_new" RENAME TO "ProjectStatus";
DROP TYPE "ProjectStatus_old";
ALTER TABLE "FormalProject" ALTER COLUMN "status" SET DEFAULT 'PROTOCOL_DRAFT';
COMMIT;

-- AlterEnum
