-- Four grades become three outcomes (Approved, Revision and resubmission, Rejected). Mapping kept for any row that exists.
UPDATE "FormalProjectReview" SET "recommendation" = CASE "grade"::text
  WHEN 'SATISFACTORY' THEN 'APPROVED'::"ReviewRecommendation"
  WHEN 'MINOR_REVISION' THEN 'REVISION'::"ReviewRecommendation"
  WHEN 'MAJOR_REVISION' THEN 'REVISION'::"ReviewRecommendation"
  WHEN 'UNSATISFACTORY' THEN 'REJECTED'::"ReviewRecommendation"
END WHERE "grade" IS NOT NULL;
ALTER TABLE "FormalProjectReview" DROP COLUMN "grade";

