-- ---------------------------------------------------------------------------
-- Hand-written: backfill, rules the database should enforce, append-only trail
-- ---------------------------------------------------------------------------

-- Results held on ExamApplication move to ExamResult (the nth attempt per trainee and exam by date).
INSERT INTO "ExamResult" ("id","traineeId","examType","applicationId","examDate","attemptNumber","result","score","sourceBatchId")
SELECT gen_random_uuid()::text, a."traineeId", a."examType", a."id", a."examDate"::date,
       row_number() OVER (PARTITION BY a."traineeId", a."examType" ORDER BY a."examDate", a."submittedAt"),
       a."result", a."score", a."sourceBatchId"
FROM "ExamApplication" a WHERE a."result" IS NOT NULL;

ALTER TABLE "CourseAttendance" ADD CONSTRAINT "CourseAttendance_rate_chk" CHECK ("ratePercent" BETWEEN 0 AND 100);
ALTER TABLE "CourseNotice" ADD CONSTRAINT "CourseNotice_rate_chk" CHECK ("ratePercent" BETWEEN 0 AND 100);
ALTER TABLE "CourseRound" ADD CONSTRAINT "CourseRound_ranking_chk" CHECK ("rankingMode" IN ('priority','fcfs'));
ALTER TABLE "CourseRound" ADD CONSTRAINT "CourseRound_dates_chk" CHECK (("endDate" IS NULL OR "endDate" >= "roundDate") AND ("registrationCloses" IS NULL OR "registrationOpens" IS NULL OR "registrationCloses" >= "registrationOpens"));

ALTER TABLE "ExamSitting" ADD CONSTRAINT "ExamSitting_dates_chk" CHECK ("opensOn" <= "closesOn" AND "closesOn" < "writtenOn");
ALTER TABLE "ExamSectionPass" ADD CONSTRAINT "ExamSectionPass_left_chk" CHECK ("sittingsLeft" BETWEEN 0 AND 4);
-- One active carried-forward pass per trainee and exam. Prisma cannot express a partial index, so it lives here only.
CREATE UNIQUE INDEX "ExamSectionPass_one_active" ON "ExamSectionPass"("traineeId","examType") WHERE "isActive";

ALTER TABLE "TraineeFeePayment" ADD CONSTRAINT "TraineeFeePayment_type_chk" CHECK ("feeType" IN ('REGISTRATION','TRAINING'));
ALTER TABLE "TraineeExemption" ADD CONSTRAINT "TraineeExemption_kind_chk" CHECK ("kind" IN ('ANZCA_PRIMARY','FRCA_PRIMARY','OTHER_BOARD'));

ALTER TABLE "FormalProject" ADD CONSTRAINT "FormalProject_route_chk" CHECK ("route" IN ('STANDARD','ACCEPTED_PAPER') AND ("route" = 'STANDARD' OR "paperJournal" IS NOT NULL));
ALTER TABLE "FormalProjectReview" ADD CONSTRAINT "FormalProjectReview_team_chk" CHECK (NOT "byTeam" OR "handedToTeamAt" IS NOT NULL);
ALTER TABLE "FormalProjectReview" ADD CONSTRAINT "FormalProjectReview_override_chk" CHECK ("lateOverrideById" IS NULL OR "lateOverrideReason" IS NOT NULL);
ALTER TABLE "FormalProjectEvent" ADD CONSTRAINT "FormalProjectEvent_visibility_chk" CHECK ("visibility" IN ('trainee','internal'));

ALTER TABLE "ApplicationEndorsement" ADD CONSTRAINT "ApplicationEndorsement_signed_chk" CHECK ("signedAt" IS NULL OR "method" IS NOT NULL);
ALTER TABLE "ApplicationEndorsement" ADD CONSTRAINT "ApplicationEndorsement_pdf_chk" CHECK ("method" IS DISTINCT FROM 'PDF' OR "signedAt" IS NULL OR "documentId" IS NOT NULL);

-- A rejection is never the Training Officer's alone. NOT VALID: existing rows are not re-checked, new and changed rows are.
ALTER TABLE "RetrospectiveRecognition" ADD CONSTRAINT "RetrospectiveRecognition_reject_chk" CHECK ("vettingStatus" <> 'REJECTED' OR "decidedByBody" = 'BOARD') NOT VALID;
ALTER TABLE "RetrospectiveRecognition" ADD CONSTRAINT "RetrospectiveRecognition_origin_chk" CHECK ("originKind" IS NULL OR "originKind" IN ('OVERSEAS_TRAINING','OTHER_SPECIALTY'));

-- The decision trail is append-only: no edits, no deletes.
CREATE FUNCTION "hkca_append_only"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN RAISE EXCEPTION '% is append-only', TG_TABLE_NAME; END $$;
CREATE TRIGGER "RetrospectiveRecognitionEvent_append_only" BEFORE UPDATE OR DELETE ON "RetrospectiveRecognitionEvent"
FOR EACH ROW EXECUTE FUNCTION "hkca_append_only"();
